import{createHash}from'node:crypto';import{mkdirSync,writeFileSync}from'node:fs';import{dirname,resolve}from'node:path';import{loadConfig}from'./config.js';import{backend,listSessions}from'./sessionStore.js';import{runDoctor}from'../commands/doctorLogic.js';import{listAdapters}from'../loop/adapters/index.js';import{listWorktrees}from'../orchestrator/worktree.js';const SECRET=/key|token|secret|password|authorization/i;function redact(v,k=''){if(SECRET.test(k))return v?'[REDACTED]':v;if(Array.isArray(v))return v.map(x=>redact(x));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([a,b])=>[a,redact(b,a)]));if(typeof v==='string')return v.replace(/(sk-|xai-|nvapi-)[A-Za-z0-9_-]{8,}/g,'[REDACTED]');return v;}export function createSupportBundle({output=`lehrosol-support-${Date.now()}.json`,limit=20}={}){output=resolve(output);const data=redact({generatedAt:new Date().toISOString(),runtime:{node:process.version,platform:process.platform,arch:process.arch},doctor:runDoctor({cwd:process.cwd()}),adapters:listAdapters().map(a=>({id:a.id,kind:a.kind,configured:a.configured,target:a.baseUrl||a.bin,model:a.model})),sessionBackend:backend(),sessions:listSessions({limit}),worktrees:listWorktrees().worktrees||[],config:loadConfig()});mkdirSync(dirname(output),{recursive:true});const text=JSON.stringify(data,null,2)+'\n';writeFileSync(output,text,{mode:0o600});return{output,sha256:createHash('sha256').update(text).digest('hex'),bytes:Buffer.byteLength(text),data};}
